// 用原Growth开工三腿与Common真实执行核同栈采购初源；不声称报价、世界或永久运输历史验收。
#include "resident/domains/commerce/freight/private_shop_freight_purchase_source.hpp"
#include "resident/domains/growth/growth_internal.hpp"
#include <iostream>
#include <limits>
#include <stdexcept>
using namespace hanmo::resident;
namespace {
int checks=0,failures=0;
// 原writer拒绝即止，保首次失败，不手补本应由writer生成的LifeActivity或货批。
void check(bool value,const char* text){++checks;if(!value){++failures;std::cerr<<"FAIL "<<text<<'\n';}}
void require(bool value,const char* text){check(value,text);if(!value)throw std::runtime_error(text);}
struct Fixture {
    std::shared_ptr<CommonCatalog> shared=std::make_shared<CommonCatalog>();CommonStore common{CommonState{},shared};GrowthCatalog catalog;GrowthState growth;GrowthQuote quote;StableId old_bag_lot,first_market_lot;
    // 初态人物与目录是最小静态夹具；钱库和所有lot均经真实Common原语建立。
    Fixture(){
        shared->items.insert("grain",{"grain",1,1,false,false});catalog.economy=catalog.regional_life=true;catalog.shops.insert("market",{"market","stall","inventory.merchant","wallet.merchant",{}});
        for(const auto& id:{StableId{"buyer"},StableId{"merchant"}}){ActorRecord a;a.id=id;a.alive=a.available=true;a.wallet_id="wallet."+id;a.inventory_id="inventory."+id;common.state().actors.insert(id,a);WalletView wallet;wallet.id=a.wallet_id;wallet.owner={Owner::Kind::actor,id,{}};wallet.balance=100;InventoryView bag;bag.id=a.inventory_id;bag.owner=wallet.owner;bag.capacity=100;require(common.apply_resources({{CreateWallet{wallet},CreateInventory{bag}}, {}}).ok,"original empty private assets");}
        require(common.apply_resources({{AddLot{"inventory.buyer","grain",2,{Owner::Kind::actor,"buyer",{}},{}},AddLot{"inventory.merchant","grain",3,{Owner::Kind::actor,"merchant",{}},{}},AddLot{"inventory.merchant","grain",8,{Owner::Kind::actor,"merchant",{}},{}}}, {}}).ok,"real old bag and distinct market lots");old_bag_lot=common.inventory("inventory.buyer")->lots.front().id;first_market_lot=common.inventory("inventory.merchant")->lots.front().id;
        InteractionContext context;context.place_id="stall";context.provider_actor_id="merchant";context.role_id="merchant.role";quote.command.kind="trade";quote.command.side="buy";quote.command.shop_id="market";quote.command.item_id="grain";quote.command.quantity=5;quote.command.payer_wallet_id="wallet.buyer";quote.command.context=context;quote.context=context;quote.duration=1;TradeTerms terms;terms.shop_id="market";terms.side="buy";terms.item_id="grain";terms.payer_wallet_id="wallet.buyer";terms.quantity=5;terms.total=11;terms.market_revision=common.inventory("inventory.merchant")->revision;terms.valid_tick=common.tick();terms.owner={Owner::Kind::actor,"buyer",{}};terms.context=context;quote.data=terms;
        require(common.begin_resource_execution_capture().ok,"begin actual Common draft capture");
    }
    // 原kernel的Action分配/占用，然后直接调用原领域资源writer；不伪造付款或LifeActivity。
    StableId start(){auto id=common.next_id("action");require(id.ok,"actual trade action allocation");ActionMutation insert;insert.kind=ActionMutation::Kind::insert;insert.action={id.value,"trade","buyer",{"buyer","merchant"},common.tick(),1};require(common.apply_action(insert).ok,"actual action envelope");for(const auto& actor:{StableId{"buyer"},StableId{"merchant"}}){ActorMutation occupy;occupy.actor_id=actor;occupy.action_id=id.value;require(common.apply_actor(occupy).ok,"actual two-person occupation");}auto result=growth::start_service_trade(common,growth,catalog,insert.action,quote);require(result.ok,"original Growth buy writer and life record");return id.value;}
};
// 原付款及两个新批都精确映射，不把背包原有同品计入本次采购。
void original_purchase(){Fixture f;auto before=capture_private_shop_freight_purchase_boundary(f.common,f.catalog,"buyer","market");require(before.ok,"original pre-action purchase boundary");auto id=f.start();const auto next=f.common.state().next_instance_id;auto result=read_private_shop_freight_purchase(f.common,f.growth,f.catalog,before.value,id);require(result.ok,"original buy source read");check(result.value.purchased_lots.size()==2&&result.value.purchased_lots.front().actual_transfer.source_lot_id==f.first_market_lot,"real FIFO fragments retained");check(result.value.purchased_lots[0].personal_lot_after.quantity==3&&result.value.purchased_lots[1].personal_lot_after.quantity==2&&result.value.purchased_lots[0].personal_lot_after.id!=f.old_bag_lot,"only real newly purchased lot identities");check(result.value.actual_debit.before->balance==100&&result.value.actual_debit.after.balance==89&&result.value.actual_credit.after.balance==111,"original equal payer and merchant money legs");check(f.common.state().next_instance_id==next&&f.common.inventory("inventory.buyer")->lots.front().quantity==2,"source read has no ID or stock write");auto bad=before.value;bad.original_common=nullptr;check(!read_private_shop_freight_purchase(f.common,f.growth,f.catalog,bad,id).ok,"no detached transient boundary");bad=before.value;++bad.identity.revision;check(!read_private_shop_freight_purchase(f.common,f.growth,f.catalog,bad,id).ok,"cross-result scope rejected");require(f.common.apply_resources({{WalletDelta{"wallet.merchant",0,true}}, {}}).ok,"real extra zero recipe");check(!read_private_shop_freight_purchase(f.common,f.growth,f.catalog,before.value,id).ok,"even zero interposed recipe is not part of this original buy");}
// 损坏暂态副本不能顶替原资金/批次；临时草稿接口生产只读，反例显式const_cast模拟坏源。
void malformed_scope(){Fixture f;auto before=capture_private_shop_freight_purchase_boundary(f.common,f.catalog,"buyer","market");require(before.ok,"bad source boundary");auto id=f.start();auto& actual=const_cast<ResourceExecutionDraft&>(f.common.resource_execution_drafts().back());const auto saved=actual;actual.operations[0].lot_flows.front().destination_lot_id=f.old_bag_lot;check(!read_private_shop_freight_purchase(f.common,f.growth,f.catalog,before.value,id).ok,"old same-item lot cannot impersonate bought lot");actual=saved;actual.operations[0].lot_flows.pop_back();check(!read_private_shop_freight_purchase(f.common,f.growth,f.catalog,before.value,id).ok,"missing actual fragment rejected");actual=saved;actual.operations[1].wallets.front().after.balance=90;check(!read_private_shop_freight_purchase(f.common,f.growth,f.catalog,before.value,id).ok,"wrong true debit rejected");actual=saved;std::get<WalletDelta>(actual.recipe.operations[2]).delta=10;check(!read_private_shop_freight_purchase(f.common,f.growth,f.catalog,before.value,id).ok,"different payee amount rejected");actual=saved;actual.operations[0].inventories.front().before->owner.id="buyer";check(!read_private_shop_freight_purchase(f.common,f.growth,f.catalog,before.value,id).ok,"market ownership substitution rejected");actual=saved;auto* record=f.growth.life_activities.find(id);record->view.amount=10;check(!read_private_shop_freight_purchase(f.common,f.growth,f.catalog,before.value,id).ok,"typed original source cannot change trade amount");record->view.amount=11;check(read_private_shop_freight_purchase(f.common,f.growth,f.catalog,before.value,id).ok,"original restored source remains readable");}
// 原款中别笔预约不丢，真实零价买入仍有两原钱包操作，不能被当作缺少资金源。
void zero_and_reserved(){Fixture f;auto reserve=f.common.next_id("action");require(reserve.ok,"real unrelated reservation ID");ActionMutation other;other.kind=ActionMutation::Kind::insert;other.action={reserve.value,"wait","buyer",{"buyer"},0,1};require(f.common.apply_action(other).ok,"real reservation action");require(f.common.apply_resources({{SetReservation{"wallet.buyer",reserve.value,40,false}}, {}}).ok,"actual prior reserved funds");std::get<TradeTerms>(f.quote.data).total=0;auto before=capture_private_shop_freight_purchase_boundary(f.common,f.catalog,"buyer","market");require(before.ok,"zero-price actual boundary after prior recipe");auto id=f.start();auto result=read_private_shop_freight_purchase(f.common,f.growth,f.catalog,before.value,id);require(result.ok,"actual zero-price buy maps");check(result.value.actual_debit.before->reserved.size()==1&&result.value.actual_debit.after.reserved.size()==1&&result.value.actual_debit.after.balance==100&&result.value.purchased_lots.size()==2,"real reservation and zero money operations preserved");}
// 普通合法Task/店钱包交易不是本人垫付；此纯消费者不扩大第一片报销策略。
void private_strategy_only(){Fixture f;auto before=capture_private_shop_freight_purchase_boundary(f.common,f.catalog,"buyer","market");require(before.ok,"private strategy original boundary");auto id=f.start();auto* typed=std::get_if<TradeTerms>(&f.growth.life_activities.find(id)->terms);typed->owner={Owner::Kind::task,"task.original",{}};std::get<TradeTerms>(f.growth.actions.find(id)->quote.data).owner=typed->owner;check(!read_private_shop_freight_purchase(f.common,f.growth,f.catalog,before.value,id).ok,"TaskOwner not promoted to personal freight");}
// 收款上溢发生在原recipe已经暂存转货与扣款之后；整recipe仍不发布，也不给采购初源。
void failed_credit_recipe(){
    Fixture f;f.common.state().wallets.find("wallet.merchant")->balance=std::numeric_limits<Integer>::max();auto boundary=capture_private_shop_freight_purchase_boundary(f.common,f.catalog,"buyer","market");require(boundary.ok,"overflow original boundary");const auto bag=*f.common.inventory("inventory.buyer"),stock=*f.common.inventory("inventory.merchant");const auto original_next=f.common.state().next_instance_id;auto point=f.common.begin_savepoint();require(point.ok,"original whole candidate savepoint");auto id=f.common.next_id("action");require(id.ok,"overflow action allocated");ActionMutation insert;insert.kind=ActionMutation::Kind::insert;insert.action={id.value,"trade","buyer",{"buyer","merchant"},f.common.tick(),1};require(f.common.apply_action(insert).ok,"overflow action inserted");for(const auto& actor:{StableId{"buyer"},StableId{"merchant"}}){ActorMutation occupy;occupy.actor_id=actor;occupy.action_id=id.value;require(f.common.apply_actor(occupy).ok,"overflow original occupation");}
    auto result=growth::start_service_trade(f.common,f.growth,f.catalog,insert.action,f.quote);check(!result.ok&&f.common.resource_execution_drafts().empty()&&!f.growth.life_activities.find(id.value)&&!f.growth.actions.find(id.value),"late merchant credit overflow publishes neither recipe nor trade source");check(f.common.wallet("wallet.buyer")->balance==100&&f.common.inventory("inventory.buyer")->lots.size()==bag.lots.size()&&f.common.inventory("inventory.merchant")->lots.front().quantity==stock.lots.front().quantity,"staged goods and payer debit stay unpublished");check(!read_private_shop_freight_purchase(f.common,f.growth,f.catalog,boundary.value,id.value).ok,"failed original trade has no readable purchase source");require(f.common.rollback_savepoint(point.value).ok,"original candidate rollback succeeds");check(f.common.state().next_instance_id==original_next&&!f.common.action(id.value)&&f.common.actor("buyer")->action_id.empty()&&f.common.actor("merchant")->action_id.empty(),"rollback restores original action ID and both occupancies");
}

// 原Common地址未变也不能让旧前界消费新捕获；原copy不继承开关，真实新买入仍沿旧writer。
void capture_lifecycle(){
 for(bool assignment:{false,true}){Fixture f;auto old=capture_private_shop_freight_purchase_boundary(f.common,f.catalog,"buyer","market");require(old.ok,"original lifecycle boundary");
  if(assignment){CommonStore clone=f.common;check(!clone.resource_execution_capture_identity(),"copy does not inherit capture identity");f.common=clone;check(!f.common.resource_execution_capture_identity(),"assignment clears original capture identity");}
  else require(f.common.finish_resource_execution_capture().ok,"finish initial capture before any trade");
  check(!capture_private_shop_freight_purchase_boundary(f.common,f.catalog,"buyer","market").ok,"inactive capture cannot issue purchase boundary");require(f.common.begin_resource_execution_capture().ok,"restart actual capture in same Common");auto fresh=capture_private_shop_freight_purchase_boundary(f.common,f.catalog,"buyer","market");require(fresh.ok,"fresh lifecycle boundary");auto id=f.start();
  check(!read_private_shop_freight_purchase(f.common,f.growth,f.catalog,old.value,id).ok,"old identity cannot consume actual new trade");check(read_private_shop_freight_purchase(f.common,f.growth,f.catalog,fresh.value,id).ok,"new identity reads original actual trade");}
}

}
int main(){try{original_purchase();malformed_scope();zero_and_reserved();private_strategy_only();failed_credit_recipe();capture_lifecycle();}catch(const std::exception& e){check(false,e.what());}std::cout<<"FREIGHT_PURCHASE_SOURCE_CHECKS="<<checks<<" FAILURES="<<failures<<'\n';return failures?1:0;}
